sql_calls.sql:
SELECT COUNT(*) AS shelf_audit_rows_june_2026
FROM store.shelf_audits
WHERE audit_ts >= '2026-06-01' AND audit_ts < '2026-07-01';

SELECT COUNT(*) AS upi_refunds_2026
FROM payments.upi_refunds
WHERE requested_ts >= '2026-01-01' AND requested_ts < '2027-01-01';

SELECT MIN(bill_ts) as min_date, MAX(bill_ts) as max_date
FROM store.pos_lines
WHERE bill_ts >= '2026-07-01';

SELECT MIN(date) as min_date, MAX(date) as max_date
FROM store.daily_sales
WHERE date >= '2026-07-01';

SELECT count(*) as april_count
FROM payments.pos_payments
WHERE ts >= '2026-04-01' AND ts < '2026-05-01';

SELECT COUNT(*) AS products_above_100
FROM store.products
WHERE price_inr > 100;

SELECT shipment_id, dispatched_ts, arrived_ts, pallets
FROM warehouse.shipments
ORDER BY dispatched_ts;

SELECT COUNT(DISTINCT bill_ref) AS bills_with_upi_attempt
FROM payments.psp_upi_report
WHERE initiated_ts >= '2026-06-01' AND initiated_ts < '2026-07-01';

SELECT COUNT(*), COUNT(bill_ref), COUNT(DISTINCT bill_ref)
FROM payments.psp_upi_report
WHERE initiated_ts >= '2026-06-01' AND initiated_ts < '2026-07-01';

SELECT SUM(units_sold) AS total_units_sold
FROM store.daily_sales
WHERE date >= '2026-06-01' AND date <= '2026-06-28';

SELECT SUM(units) AS total_units
FROM store.store_orders
WHERE created_ts >= '2026-06-01' AND created_ts < '2026-07-01';

SELECT *
FROM store.products
ORDER BY sku;

SELECT DISTINCT gtin_scanned, sku_scanned
FROM store.pos_lines
ORDER BY sku_scanned;

SELECT COUNT(*) AS total_counts
FROM store.stock_counts
WHERE count_ts >= '2026-01-01' AND count_ts < '2026-04-01';

SELECT *
FROM warehouse.shipping_notice_lines
WHERE order_id = 'SO-260612' AND sku = 'RICE-SM-5KG';

SELECT *
FROM warehouse.pallets
WHERE shipment_id = 'SHP-260613' AND sscc = '029000010000010450';

SELECT *
FROM store.goods_receipts
WHERE shipment_id = 'SHP-260613' AND sscc = '029000010000010450';

SELECT *
FROM warehouse.pick_confirmations
WHERE order_id = 'SO-260612' AND sku = 'RICE-SM-5KG';
